PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { dbr:Thedi_Vandha_Mappillai dbr:Jet_Storm }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?dir1 . }
  OPTIONAL { ?film dbo:director ?dir2 . }
  BIND (COALESCE(?dir1, ?dir2) AS ?director)

  # director's death date (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?date1 . }
  OPTIONAL { ?director dbo:deathDate ?date2 . }
  BIND (COALESCE(?date1, ?date2) AS ?deathDate)
}
LIMIT 100

